-- Aurora cutover: recreate Supabase's public->public foreign keys on Aurora (VTID-04755)
--
-- Generated read-only from Supabase (inmkhvwdcuyhnxkgfvsb) pg_constraint on 2026-10-09.
-- Aurora has ZERO foreign keys in public (DMS full loads don't copy them), so
-- PostgREST on Aurora reports "0 Relationships" and every embedded select
-- (e.g. select=*,profiles(*)) would fail after the cutover.
--
-- RUN ONLY AFTER the final full load (runbook Step 5): TRUNCATE_BEFORE_LOAD
-- fails on tables referenced by a foreign key, so these must not exist while
-- DMS loads. NOT VALID = enforced for new writes and visible to PostgREST,
-- without scanning existing rows. public->auth FKs (127) are deliberately
-- NOT included: auth.users is not in Aurora.
--
-- Regenerate right before the window if Supabase's schema changed since.
-- One statement per line: run with scripts/aws/aurora-run-sql.sh.
-- 2026-10-09: profiles(user_id) is UNIQUE on Supabase but was not on Aurora; two FKs need it.
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_user_id_key' AND conrelid = 'public.profiles'::regclass) THEN ALTER TABLE public.profiles ADD CONSTRAINT profiles_user_id_key UNIQUE (user_id); END IF; END $do$;
-- Each FK is skipped if it already exists, so this file can be re-run.
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'access_audit_log_tenant_id_fkey' AND conrelid = 'public.access_audit_log'::regclass) THEN ALTER TABLE access_audit_log ADD CONSTRAINT access_audit_log_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id) ON DELETE RESTRICT NOT VALID; END IF; END $do$;
